import base64
import json
from datetime import datetime, timezone

import streamlit as st
import streamlit.components.v1 as components

try:
    from backend import CATEGORIES_TRADFI, CATEGORIES_CRYPTO, MACRO_BENCHMARKS, CRYPTO_BENCHMARKS, fetch_realtime_quotes
except ImportError as exc:
    st.error(f"Não foi possível importar backend.py: {exc}")
    st.stop()

st.set_page_config(page_title="OMNI Research Engine", page_icon="⚡", layout="wide", initial_sidebar_state="collapsed")


def build_overview(module):
    source = CATEGORIES_CRYPTO if module == "crypto" else {k: v for k, v in CATEGORIES_TRADFI.items() if "Crypto" not in k and "Digital" not in v.get("tag", "")}
    categories = []
    symbols = []
    for category, data in source.items():
        assets = []
        for item in data.get("assets", []):
            name, symbol = item[0], item[1]
            assets.append((name, symbol))
            if symbol not in symbols:
                symbols.append(symbol)
        categories.append((category, assets))
    benchmark_defs = list(MACRO_BENCHMARKS if module == "tradfi" else CRYPTO_BENCHMARKS)
    if module == "tradfi":
        benchmark_defs.extend([
            {"key": "NDX", "ticker": "^NDX", "label": "NASDAQ 100", "badge": "Direct API"},
            {"key": "VIX", "ticker": "^VIX", "label": "VOLATILITY INDEX", "badge": "Direct API"},
        ])
    symbols.extend(item["ticker"] for item in benchmark_defs if item.get("ticker"))
    symbols = tuple(dict.fromkeys(symbols))
    try:
        raw = fetch_realtime_quotes(symbols, brapi_token="")
    except Exception as exc:
        raw = {symbol: {"price": 0.0, "change": 0.0} for symbol in symbols}
        error = str(exc)
    else:
        error = None
    timestamp = datetime.now(timezone.utc).isoformat()
    assets = []
    for category, category_assets in categories:
        for name, symbol in category_assets:
            quote = raw.get(symbol, {"price": 0.0, "change": 0.0})
            price = float(quote.get("price", 0) or 0)
            assets.append({
                "name": name, "symbol": symbol, "price": price,
                "changePercent": float(quote.get("change", 0) or 0),
                "assetClass": "crypto" if "-USD" in symbol else "equity",
                "source": "Yahoo Finance / BRAPI", "dataStatus": "live" if price else "unavailable",
                "isStale": not bool(price), "timestamp": timestamp, "sparkline": [], "error": None,
            })
    for definition in benchmark_defs:
        ticker = definition.get("ticker")
        if not ticker:
            continue
        quote = raw.get(ticker, {"price": 0.0, "change": 0.0})
        price = float(quote.get("price", 0) or 0)
        dashboard_symbol = definition.get("key", ticker)
        assets.append({
            "name": definition["label"], "symbol": dashboard_symbol, "ticker": ticker, "price": price,
            "changePercent": float(quote.get("change", 0) or 0),
            "assetClass": "crypto" if "-USD" in ticker else "equity",
            "source": definition.get("badge", "provider"), "dataStatus": "live" if price else "unavailable",
            "isStale": not bool(price), "timestamp": timestamp, "sparkline": [], "error": None,
        })
    available = [item for item in assets if item["price"] > 0]
    return {
        "module": module, "asOf": timestamp, "source": "Yahoo Finance / BRAPI fallback",
        "dataStatus": "live" if available else "unavailable", "isStale": not bool(available),
        "assets": assets,
        "categories": [{"name": n, "assets": [{"name": a, "symbol": s} for a, s in items]} for n, items in categories],
        "kpis": {"advancing": sum(x["changePercent"] > 0 for x in available), "declining": sum(x["changePercent"] < 0 for x in available), "total": len(assets), "available": len(available)},
        "errors": ([error] if error else []) + ([] if available else ["No provider quote returned for the selected symbols."]),
    }


@st.cache_data(ttl=60, show_spinner=False)
def load_bootstrap():
    return {"tradfi": build_overview("tradfi"), "crypto": build_overview("crypto")}


with st.spinner("Carregando dados de mercado..."):
    bootstrap = load_bootstrap()

html = base64.b64decode("").decode("utf-8")
html = html.replace("__OMNI_BOOTSTRAP_PLACEHOLDER__", json.dumps(bootstrap, ensure_ascii=False))
components.html(html, height=2400, scrolling=True)
